#!/usr/bin/env python3
"""Append completed causal timing evidence and current-cone scheduling limits."""
import csv,shutil,time
from retained_prefix_workflow import D,read,write,sha
r=read(D/'timing_cone_progress_summary_01.json');assert r['passed'];paper=D/'paper';data=paper/'data'
with (data/'current_cone_source_distances_v14.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['net','pin','current_physical_s','optimistic_shortest_s','gain_s','stop'])
 for q in r['current_worst_cone_connections']:w.writerow([q['net'],q['pin'],q['current_physical_s'],q['cost_s'],q['optimistic_gain_s'],q['stop']])
(data/'timing_cone_progress_v14.tex').write_text(r'''\paragraph{The endpoint-invariant repair is masked by a strictly later LUT input.}
The previously unresolved SPMV masking mechanism is now identified from a separate, disabled-by-default native timing observer. It exports the existing Tatum graph, constraints, edge delays and arrival/required tags at 17 digits. The frozen repair implementation and its 45 source bindings remain unchanged. Three successful analysis-only observations preserve their original route and complete endpoint vectors exactly: observer off and on for the accepted plateau, and observer on for the rejected successor. No routing is repeated. Each exported graph contains 66118 nodes, 176948 edges and 382088 tags.

The successor changes only one timing-edge delay, corresponding to 6997/pin~1, and only that connection's receiving node changes setup arrival. Its next LUT output is still determined by 6927/pin~1. The repaired input was already 129.686484 ps earlier than that unique winning input; after repair it is 315.512061 ps earlier. All incoming arrival-plus-edge maxima reproduce native float32 arithmetic in both states. Thus this is strictly dominant-input masking, not an equal-delay tie or a failure to adopt the physical shortcut. All 129 reachable downstream endpoints retain their arrival and required tags. The candidate remains legal but both acceptance policies reject its unchanged CPD and endpoint vector. The accepted plateau remains at CPD 7.034697713237392 ns, one SB pair, 967 CB sources and wirelength 148445. The earlier two-component setup gain does not unlock subsequent CPD improvement in this sequence.

\paragraph{Current endpoint sensitivity changes where the next search is spent.}
A new read-only selector starts from the actual minimum-slack endpoint and recursively retains all exact maximum-arrival predecessors for its launch domain, recording unresolved recurrences as unknown. This is distinct from downstream reachability and from selecting every connection with a near-critical pin slack. The SPMV current worst endpoint is \texttt{fetcher.fifo\_col\_id\_30.gb.D[0]}. Its complete traced cone has 14 nodes and 13 edges, with six external routed connections: 6157/pin~12, 6373/pin~1, 6923/pin~1, 6927/pin~1, 6998/pin~1 and 7773/pin~1. There are no unresolved non-source nodes.

All six current physical connection delays equal their exact full-device SOURCE-only shortest distances in the actual zero-RC graph, even with background occupancy and retained branches relaxed. Returned path edges are checked against the XML-bound graph and native-rounded switch delays. The first three queries cover the dominant masking input's upstream cone; the full-endpoint pass reuses those exact cases and queries only the other three. This establishes no remaining physical-distance gain for those six fixed-terminal connections. It is a conditional limit of this route-only intervention, not a global placement, pin-assignment, logic or FPGA-routing optimum. Endpoint-Pareto work outside the worst cone is not excluded. The selector currently supplies scheduling evidence; it has not yet been promoted as an integrated repair-controller optimization or claimed to improve quality.

\paragraph{Diagnostic cost and preserved engineering failures.}
The three successful observation child processes take 47.320 s together, including 25.559 s of native execution. One earlier observation takes 11.985 s before its automatically selected TBB configuration hits the thread guard; the successful observer explicitly matches the baseline's serial engines. A parser error after two successful observations is fixed without repeating those observations. Initial missing-server dependency, recovered executable packaging and parser failures remain in the evidence. The three build attempts take 13.038, 194.893 and 162.088 s, reported as engineering cost rather than route cost. Causal graph analysis takes 8.179 s, automatic endpoint-cone selection 3.881 s, and the two source-query batches 4.460 and 4.695 s, with three query cases reused in the latter. These are development measurements with nested times kept separate; no U-version historical timing is substituted.

The previously prepared complete physical-audit cache is now exercised on fresh native observations: independent audit components take 4.343 and 4.394 s, inside complete evaluation times of 17.619 and 16.456 s. This establishes successful use, not a matched whole-process speedup. Further research moves to untouched BNN Tf, strong native A0 and old R1 routes with fresh endpoint selection and independent strict/endpoint branches. BNN has a different physical graph and must receive its own graph binding before capacity queries. These registered observations are not yet presented as repair results or a terminating experimental matrix.
''')
main=paper/'main.tex';s=main.read_text();needle='\\input{data/timing_cone_progress_v14.tex}';assert needle not in s;assert '\\section{Conclusion}' in s;main.write_text(s.replace('\\section{Conclusion}',needle+'\n\n\\section{Conclusion}'))
with (paper/'claims_evidence.md').open('a') as f:
 f.write('\n| C106 | SPMV合法6997p1缩短被严格占优的6927p1输入遮蔽，非并列路径或未采用 | [实际时序锥](../spmv_timing_cone_analysis_01.json)、[观察复用](../timing_cone_spmv_dev_04/completion.json)、[汇总](../timing_cone_progress_summary_01.json) | 仅1延迟边/1arrival节点变化；同LUT主导输入差129.686→315.512ps，129可达端点不变，native float32最大递推核验。3成功观察47.320s，另1保护失败11.985s；0新route，CPD仍7.034697713ns |\n')
 f.write('| C107 | 从当前最差端点自动回溯六路由连接，均达固定端点乐观最短距离 | [自动选择](../spmv_current_worst_arrival_cone_01.json)、[图绑定距离](../spmv_current_worst_source_reference_01/completion.json)、[通用选择器](../current_sta_arrival_cone.py)、[新BNN登记](../timing_cone_bnn_dev_01/registration.json) | 14节点13边、无未知递推；3新查询+3严格匹配复用，六项gain=0。仅当前固定端点零RC路由干预限制，不排除端点向量其他收益/映射布局变化。选择器尚未集成提升；BNN不同图需独立绑定 |\n')
with (paper/'mechanisms_and_ablation.md').open('a') as f:f.write('\nC106–C107将C103–C105时未解决的遮蔽问题定位：6997p1实际缩短但6927p1严格占优，无需把此案例误判为并列路径组合修复。新通用选择器从当前端点回溯全部精确max前驱；SPMV最差路径六连接均达SOURCE-only最短距离，固定端点重布线继续降CPD空间受限。移至未修复BNN起点，保留次级端点目标；不增加整体停止条件。FULL审查缓存现已用于新native观察，但没有整体速度对照。[证据](../timing_cone_progress_summary_01.json)。\n')
with (paper/'README.md').open('a') as f:f.write('\nC106–C107更新：实际时序锥已定位严格占优输入遮蔽，当前最差路径六连接均达固定端点物理最短距离。自动回溯选择器已实跑但尚未集成控制器；BNN原始Tf/A0/R1观察登记继续。SPMV CPD不变；新增结果仍仅本地，旧快照f7167bd未包含。\n')
ledger=data/'evidence_v14_ledger.json';history=data/'ledger_history_20261113/before_timing_cone_progress_01.json';assert not history.exists();shutil.copy2(ledger,history);l=read(ledger)
names=[str(p.relative_to(D)) for p in map(__import__('pathlib').Path,r['source_sha256'])]
names+=['timing_cone_progress_summary_01.json','export_timing_cone_progress.py','paper/data/current_cone_source_distances_v14.csv','paper/data/timing_cone_progress_v14.tex']
l['sources_sha256'].update({n:sha(D/n) for n in names});l['updated_at']=time.time();l['timing_cone_progress']=dict(claims=['C106','C107'],summary='timing_cone_progress_summary_01.json',quality_promoted=False,new_work_pushed=False);write(ledger,l)
print(dict(claims=['C106','C107'],sources=len(l['sources_sha256'])))
